const aiResponse = JSON.parse($input.first().json.text);

return [
  {
    json: aiResponse
  }
];

const data = $input.first().json;

const html = `
<!DOCTYPE html>
<html>
<head>
<style>
body{
    font-family:Arial,sans-serif;
    background:#f4f4f4;
    padding:30px;
}
.container{
    max-width:700px;
    margin:auto;
    background:white;
    border-radius:10px;
    padding:30px;
    box-shadow:0 0 10px rgba(0,0,0,.1);
}
h1{
    color:#2c3e50;
}
.score{
    font-size:32px;
    color:#27ae60;
    font-weight:bold;
}
ul{
    padding-left:20px;
}
li{
    margin-bottom:8px;
}
.section{
    margin-top:25px;
}
</style>
</head>

<body>

<div class="container">

<h1>🤖 AI Resume Review</h1>

<p class="score">
ATS Score: ${data.ats_score}/100
</p>

<div class="section">
<h2>Professional Summary</h2>
<p>${data.professional_summary}</p>
</div>

<div class="section">
<h2>✅ Strengths</h2>
<ul>
${data.strengths.map(item=>`<li>${item}</li>`).join("")}
</ul>
</div>

<div class="section">
<h2>⚠ Weaknesses</h2>
<ul>
${data.weaknesses.map(item=>`<li>${item}</li>`).join("")}
</ul>
</div>

<div class="section">
<h2>📚 Missing Skills</h2>
<ul>
${data.missing_skills.map(item=>`<li>${item}</li>`).join("")}
</ul>
</div>

<div class="section">
<h2>💡 Suggestions</h2>
<ul>
${data.suggestions.map(item=>`<li>${item}</li>`).join("")}
</ul>
</div>

</div>

</body>
</html>
`;

return [{
    json:{
        ...data,
        emailBody: html
    }
}];
